import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import org.springframework.stereotype.Service;

/**
 * Keeps every message sent so far, in memory, for the lifetime of the application.
 */
@Service
public class MessageStore {

    private final List<ContactMessage> messages = new ArrayList<>();

    public synchronized void add(ContactMessage message) {
        messages.add(message);
    }

    /**
     * @return a snapshot of all messages, the most recently sent first
     */
    public synchronized List<ContactMessage> newestFirst() {
        List<ContactMessage> copy = new ArrayList<>(messages);
        Collections.reverse(copy);
        return copy;
    }
}
