+package com.example.contact;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final MessageStore store;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+
+        name.addValueChangeListener(event -> send.setEnabled(true));
+        email.addValueChangeListener(event -> send.setEnabled(true));
+        phone.addValueChangeListener(event -> send.setEnabled(true));
+        message.addValueChangeListener(event -> send.setEnabled(true));
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+
+        send.addClickListener(event -> submit());
+        addAttachListener(event -> Shortcuts.addShortcutListener(this, this::submitIfEnabled, Key.ENTER)
+                .listenOn(event.getUI())
+                .bindLifecycleTo(this));
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(2);
+        grid.setItems(store.newestFirst());
+
+        FormLayout form = new FormLayout(name, email, phone, message, send);
+        form.setColspan(message, 2);
+
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add("You have unsent input in the contact form. Leave the page and discard it?");
+        Button keepEditing = new Button("Keep editing", event -> {
+            pendingNavigation = null;
+            leaveDialog.close();
+        });
+        Button discard = new Button("Discard", event -> {
+            leaveDialog.close();
+            ContinueNavigationAction proceed = pendingNavigation;
+            pendingNavigation = null;
+            if (proceed != null) {
+                proceed.proceed();
+            }
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(keepEditing, discard);
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, grid, leaveDialog);
+    }
+
+    private void submitIfEnabled() {
+        if (send.isEnabled() && !leaveDialog.isOpened()) {
+            submit();
+        }
+    }
+
+    private void submit() {
+        if (!validate()) {
+            return;
+        }
+        store.add(new ContactMessage(name.getValue().trim(), email.getValue().trim(),
+                phone.getValue().trim(), message.getValue().trim()));
+        grid.setItems(store.newestFirst());
+        Notification.show("Message sent");
+
+        // Clearing fires value change events that would re-enable Send, so disable it afterwards.
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+
+        if (name.getValue().trim().isEmpty()) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+        }
+
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+        } else if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+        }
+
+        String messageValue = message.getValue().trim();
+        if (messageValue.isEmpty()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            message.setInvalid(true);
+        }
+
+        return !(name.isInvalid() || email.isInvalid() || message.isInvalid());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedInput()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+}
