+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private ContactView contact() {
+        return navigate(ContactView.class);
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        name().setValue(name);
+        email().setValue(email);
+        phone().setValue(phone);
+        message().setValue(message);
+    }
+
+    private boolean notificationShown(String text) {
+        return $(Notification.class).all().stream()
+                .anyMatch(n -> String.valueOf(n.getElement().getProperty("text")).contains(text));
+    }
+
+    @Test
+    void showsHeadingFieldsAndEnabledSendOnEmptyForm() {
+        contact();
+        assertEquals("Contact", $(com.vaadin.flow.component.html.H1.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptySubmitMarksFieldsInvalidAndSendsNothing() {
+        contact();
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(notificationShown("Message sent"));
+    }
+
+    @Test
+    void invalidEmailAndTooLongMessageAreReported() {
+        contact();
+        fill("Ann", "not-an-email", "", "x".repeat(501));
+        test(send()).click();
+
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertEquals("Ann", name().getValue());
+    }
+
+    @Test
+    void validSubmitSendsAndClearsTheForm() {
+        contact();
+        fill("Bea", "bea@example.com", "", "Hello there");
+        test(send()).click();
+
+        assertTrue(notificationShown("Message sent"));
+        assertEquals("", name().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+
+        // Editing any field re-enables Send.
+        name().setValue("Bea again");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterKeySendsTheMessage() {
+        contact();
+        fill("Cy", "", "+358 40 123", "Call me");
+        fireShortcut(Key.ENTER);
+
+        assertTrue(notificationShown("Message sent"));
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        assertEquals("Cy", grid.getGenericDataView().getItem(0).name());
+    }
+
+    @Test
+    void sentMessagesAreListedNewestFirstAndSurviveNavigation() {
+        contact();
+        fill("First", "first@example.com", "", "one");
+        test(send()).click();
+        fill("Second", "", "555", "two");
+        test(send()).click();
+
+        navigate(ContactView.class);
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        List<ContactMessage> items = grid.getGenericDataView().getItems().toList();
+        assertEquals(List.of("Second", "First"), items.stream().map(ContactMessage::name).toList());
+    }
+
+    @Test
+    void leavingWithInputAsksFirstAndKeepEditingStaysPut() {
+        contact();
+        name().setValue("Dee");
+
+        test($(RouterLink.class).withText("About").single()).click();
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertEquals("Dee", name().getValue());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertFalse(dialog.isOpened());
+        assertEquals("Dee", name().getValue());
+        assertInstanceOf(ContactView.class, UI.getCurrent().getCurrentView());
+    }
+
+    @Test
+    void discardingNavigatesToAbout() {
+        contact();
+        name().setValue("Eve");
+
+        test($(RouterLink.class).withText("About").single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, UI.getCurrent().getCurrentView());
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotInterrupt() {
+        contact();
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertFalse($(Dialog.class).exists());
+        assertInstanceOf(AboutView.class, UI.getCurrent().getCurrentView());
+    }
+}
